#!/usr/bin/env python3
"""altered-arrays.py <seed> [ts|js]: Arrays of every storage, ALTERED in every way that puts something in front of Array.prototype's own methods or changes what a method must do (own properties under method names, constructor, symbols: iterator, isConcatSpreadable, species by the constructor, toPrimitive; toString | toJSON | valueOf | then | join of one's own; another prototype by four roads, a prototype that inherits from Array.prototype with overrides, null; heirs of Array; frozen | sealed | not extensible; a length that cannot be written; getters at indices; harmless names), by direct text and from behind a function, before and AFTER the array has passed the same site unaltered; then every built-in method by its name in the text. As plain Bun or a throw."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
TS = (sys.argv[2] if len(sys.argv) > 2 else 'ts') == 'ts'
R = random.Random(seed)
A = ': any' if TS else ''; AS = ' as any' if TS else ''
out = []; w = out.append
w('// generated by altered-arrays.py %d' % seed)
if TS: w('declare const console: { log(...values: unknown[]): void };')
w('const show = (v%s, d = 0)%s => { if (v === null) return "null"; if (v === undefined) return "u"; const t = typeof v; if (t === "number") return Object.is(v, -0) ? "-0" : String(v); if (t === "string") return JSON.stringify(v); if (t === "function") return "fn"; if (t === "symbol") return "sym"; if (t !== "object") return String(v); if (d > 2) return ".."; if (Array.isArray(v)) { const p = []; for (let i = 0; i < Math.min(v.length, 30); i++) { const e = Object.getOwnPropertyDescriptor(v, i); p.push(!e ? "_" : "value" in e ? show(e.value, d + 1) : "<acc>"); } const names = Reflect.ownKeys(v).filter(k => typeof k === "symbol" || (k !== "length" && !/^\\d+$/.test(k))).map(String).join(); return "[" + p.join() + "]" + v.length + (names ? "{" + names + "}" : "") + (Object.getPrototypeOf(v) === Array.prototype ? "" : "P") + (Object.isExtensible(v) ? "" : "X"); } if (v instanceof Set) return "Set" + show([...v], d + 1); if (typeof v.next === "function") return "iter"; if (typeof v.then === "function") return "thenable"; return "{" + Object.keys(v).map(k => k + ":" + show(v[k], d + 1)).join() + "}"; };' % (A, ': string' if TS else ''))
w('const recs = [{ id: 0 }, { id: 1 }, { id: 2 }];')
w('class Mine extends Array { map(...a%s)%s { return "Mine.map"; } }' % (': any[]' if TS else '', ': any' if TS else ''))
w('class Plain extends Array {}')
MAKERS = ['[1, 2, 3]', '[0.5, 1.5, 2.5]', '["a", "b", "c"]', '[recs[0], recs[1], recs[2]]', '[1, "a", null, undefined]', '[]', '[3, 1, 2].map(x => x)', '[1, , 3]', 'new Array(3)', 'new Array(3).fill(7)', 'Array.from({ length: 3 }, (_, i) => i)', 'Array.of(4, 5)', '[[1], [2, [3]]]', '"x,y".split(",")', 'Object.keys({ k: 1, l: 2 })', '[5, 6].concat([7])', '[5, 6, 7].slice(1)', '[...[8, 9]]', 'rest(1, 2)', 'new (Plain%s)(1, 2, 3)' % AS, 'Plain.from([1, 2])', 'new (Mine%s)(1, 2, 3)' % AS]
w('function rest(...r%s) { return r; }' % (': any[]' if TS else ''))
METHODS = ['push', 'pop', 'shift', 'unshift', 'splice', 'slice', 'concat', 'map', 'filter', 'forEach', 'reduce', 'reduceRight', 'some', 'every', 'find', 'findIndex', 'findLast', 'findLastIndex', 'indexOf', 'lastIndexOf', 'includes', 'join', 'reverse', 'sort', 'fill', 'copyWithin', 'flat', 'flatMap', 'at', 'keys', 'values', 'entries', 'toString', 'toLocaleString', 'with', 'toSorted', 'toReversed', 'toSpliced']
def marker(n): return '(function () { return "own %s"; })' % n
ALTER = []
for m in METHODS: ALTER.append(('own ' + m, 'a.%s = %s;' % (m, marker(m))))
ALTER += [('own %s by a key' % m, 'a[%s] = %s;' % ('"%s" + ""' % m, marker(m))) for m in ['push', 'map', 'slice', 'join', 'indexOf']]
ALTER += [('own %s defined' % m, 'Object.defineProperty(a, "%s", { value: %s, configurable: true });' % (m, marker(m))) for m in ['push', 'map', 'forEach', 'includes', 'at']]
ALTER += [('own %s a getter' % m, 'Object.defineProperty(a, "%s", { get() { return %s; }, configurable: true });' % (m, marker(m))) for m in ['pop', 'filter', 'concat']]
ALTER += [('own %s assigned' % m, 'Object.assign(a, { %s: %s });' % (m, marker(m))) for m in ['shift', 'reduce', 'sort']]
ALTER += [('own %s undefined' % m, 'a.%s = undefined;' % m) for m in ['push', 'map', 'join']]
ALTER += [
 ('constructor with species', 'a.constructor = { [Symbol.species]: function (n%s) { return { length: 0, made: "species" }; } };' % A), ('constructor undefined', 'a.constructor = undefined;'), ('constructor Object', 'a.constructor = Object;'), ('constructor Mine', 'a.constructor = Mine;'), ('constructor a number', 'a.constructor = 5;'),
 ('own iterator', 'a[Symbol.iterator] = function* () { yield "mine"; };'), ('not spreadable', 'a[Symbol.isConcatSpreadable] = false;'), ('toPrimitive', 'a[Symbol.toPrimitive] = () => "prim";'), ('toJSON', 'a.toJSON = () => "json";'), ('valueOf', 'a.valueOf = () => 42;'), ('then', 'a.then = (r%s) => r("then");' % A), ('toStringTag', 'a[Symbol.toStringTag] = "Tag";'),
 ('setPrototypeOf an heir', 'Object.setPrototypeOf(a, Object.create(Array.prototype, { map: { value: %s }, push: { value: %s } }));' % (marker('map'), marker('push'))), ('__proto__ =', 'a.__proto__ = { __proto__: Array.prototype, slice: %s, join: %s };' % (marker('slice'), marker('join'))), ('Reflect.setPrototypeOf', 'Reflect.setPrototypeOf(a, Mine.prototype);'), ('prototype null', 'Object.setPrototypeOf(a, null);'), ('prototype Object.prototype', 'Object.setPrototypeOf(a, Object.prototype);'), ('prototype with elements', 'Object.setPrototypeOf(a, Object.create(Array.prototype, { 1: { value: "under", writable: true, configurable: true, enumerable: true } }));'), ('prototype there and back', 'Object.setPrototypeOf(a, Mine.prototype); Object.setPrototypeOf(a, Array.prototype);'), ('prototype a proxy', 'Object.setPrototypeOf(a, new Proxy(Array.prototype, { get(t, k, r) { return k === "map" ? %s : Reflect.get(t, k, r); } }));' % marker('map')),
 ('frozen', 'Object.freeze(a);'), ('sealed', 'Object.seal(a);'), ('not extensible', 'Object.preventExtensions(a);'), ('length read-only', 'Object.defineProperty(a, "length", { writable: false });'), ('a getter at 0', 'Object.defineProperty(a, 0, { get() { return "got"; }, configurable: true, enumerable: true });'), ('a getter at 1 that pushes', 'Object.defineProperty(a, 1, { get() { if (a.length < 9) Array.prototype.push.call(a, "grown"); return "got"; }, configurable: true, enumerable: true });'), ('read-only at 0', 'Object.defineProperty(a, 0, { value: "fixed", writable: false });'), ('sparse', 'a[5000] = "far";'), ('length cut', 'a.length = 1;'), ('length grown', 'a.length = 6;'),
 ('harmless names', 'a.pos = 1; a.end = 2;'), ('many harmless names', 'for (let k = 0; k < 9; k++) a["n" + k] = k;'), ('a harmless symbol', 'a[Symbol("s")] = 1;'), ('a name, then deleted', 'a.push = %s; delete a.push;' % marker('push')), ('a name and a method name', 'a.pos = 1; a.map = %s;' % marker('map')), ('index, input, groups', 'a.index = 0; a.input = "x"; a.groups = undefined;'), ('raw', 'a.raw = ["r"];'), ('nothing', ''),
]
USES = ['a.push(9)', 'a.push(9, "x")', 'a.pop()', 'a.shift()', 'a.unshift(0)', 'a.splice(1, 1)', 'a.splice(0, 0, "in")', 'a.slice(1)', 'a.slice()', 'a.concat([9])', '[0].concat(a)', 'a.map((x%s) => x)' % A, 'a.filter(() => true)', '(() => { const r%s = []; a.forEach((x%s) => r.push(x)); return r; })()' % (': any[]' if TS else '', A), 'a.reduce((s%s, x%s) => s + show(x), "")' % (A, A), 'a.reduceRight((s%s, x%s) => s + show(x), "")' % (A, A), 'a.some((x%s) => x === 2)' % A, 'a.every((x%s) => x !== 2)' % A, 'a.find((x%s) => x === 2)' % A, 'a.findIndex((x%s) => x === 2)' % A, 'a.findLast(() => true)', 'a.findLastIndex(() => true)', 'a.indexOf(2)', 'a.lastIndexOf(2)', 'a.includes(2)', 'a.includes(undefined)', 'a.join("-")', 'a.reverse()', 'a.sort()', 'a.fill(0, 1)', 'a.copyWithin(0, 1)', 'a.flat()', 'a.flatMap((x%s) => [x, x])' % A, 'a.at(-1)', '[...a.keys()]', '[...a.values()]', '[...a.entries()]', 'a.toString()', 'a.toLocaleString()', 'a.with(0, "w")', 'a.toSorted()', 'a.toReversed()', 'a.toSpliced(0, 1)', 'a.length', '[...a]', 'Array.from(a)', 'String(a)', '`${a}`', 'a + ""', 'JSON.stringify(a)', '(() => { const [x, y] = a; return [x, y]; })()', '(() => { const r = []; for (const x of a) r.push(x); return r; })()', '(() => { const r = []; for (const k in a) r.push(k); return r; })()', 'rest(...a)', 'Math.max(...a)', 'new Set(a)', 'Object.keys(a)', 'Object.entries(a)', 'Array.isArray(a)', 'a instanceof Array', 'a.constructor === Array', 'Object.prototype.toString.call(a)', 'a[0]', 'a[1]', '(a[0] = "st", a[0])', '(a[a.length] = "end", a.length)', '(a.length = 2, a.length)', 'delete a[0]', '0 in a', 'a.hasOwnProperty(1)']
w('const attempt = (f%s)%s => { try { return show(f()); } catch (e) { return "THROWS " + (e%s).name; } };' % (': () => unknown' if TS else '', ': string' if TS else '', ' as Error' if TS else ''))
N = 34
rows = []
for n in range(N):
    use = R.choice(USES); rows.append(use)
    w('function u%d(a%s) { return %s; }' % (n, A, use))
w('function alter(k%s, a%s) { switch (k) {' % (': number' if TS else '', A))
picked = R.sample(range(len(ALTER)), 30)
for i, k in enumerate(picked): w('  case %d: { %s break; }' % (i, ALTER[k][1]))
w('} }')
w('const NAMES = %s;' % repr([ALTER[k][0] for k in picked]).replace("'", '"'))
makers = R.sample(MAKERS, 7)
w('const MAKERS%s = [%s];' % (': (() => any)[]' if TS else '', ', '.join('() => %s' % m for m in makers)))
w('const USES%s = [%s];' % (': ((a: any) => unknown)[]' if TS else '', ', '.join('u%d' % n for n in range(N))))
w('for (let turn = 0; turn < 40; turn++) for (const make of MAKERS) for (const use of USES) attempt(() => use(make()));')
w('for (let m = 0; m < MAKERS.length; m++) for (let k = 0; k < NAMES.length; k++) for (let u = 0; u < USES.length; u++) { const a = MAKERS[m]%s(); const r = attempt(() => { alter(k, a); return "ok"; }); if (r !== "\\"ok\\"") { console.log(m + " " + NAMES[k] + " " + u + " alter: " + r); continue; } console.log(m + " " + NAMES[k] + " " + u + ": " + attempt(() => USES[u]%s(a))); console.log(m + " " + NAMES[k] + " " + u + " after: " + attempt(() => a)); }' % ('!' if TS else '', '!' if TS else ''))
# made and altered in one function
for n in range(26):
    k = R.randrange(len(ALTER)); use = R.choice(USES); m = R.choice(MAKERS[:19])
    form = R.randrange(5)
    body = ['const a%s = %s; %s return %s;' % (A, m, ALTER[k][1], use), 'const a%s = %s; hidden(a, (a%s) => { %s }); return %s;' % (A, m, A, ALTER[k][1], use), 'const a%s = %s; const first = attempt(() => %s); %s return first + attempt(() => %s);' % (A, m, use, ALTER[k][1], use), 'const a%s = %s; for (let i = 0; i < 2; i++) { if (i) { %s } said.push(attempt(() => %s)); } return said.splice(0).join();' % (A, m, ALTER[k][1], use), 'const a%s = %s; const b = a; { const a = b; %s } return %s;' % (A, m, ALTER[k][1], use)][form]
    w('function g%d() { %s }' % (n, body))
out.insert(len(out) - 26, 'const said%s = []; function hidden(a%s, f%s) { f(a); }' % (': string[]' if TS else '', A, ': (a: any) => void' if TS else ''))
w('for (let turn = 0; turn < 3; turn++) [%s].forEach((f, i) => console.log("made here " + turn + " " + i + ": " + attempt(f)));' % ', '.join('g%d' % n for n in range(26)))
print('\n'.join(out))
